// auth-security · кейсы auth-06, auth-07, auth-15, auth-16 (.qa/tests/auth-security/)
// «כניסה כעובד» — действие внутри приложения админа (без паролей). Сессия admin.json не перезаписывается:
// режим живёт только в контексте теста, в конце — «חזרה לחשבון הניהול».
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  const dialog = page.getByRole('dialog');
  await expect(dialog.getByText('כניסה כעובד')).toBeVisible();
  await dialog.getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('הכניסה כעובד נכשלה')).toHaveCount(0);
}

async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('צוות והרשאות').first()).toBeVisible();
}

test.describe('auth-security — כניסה כעובד', () => {
  test.use({ storageState: auth('admin') });

  test('מנהל נכנס כנציג, רואה חיווי, הרשאות הנציג, וחוזר לחשבון הניהול #6a8da3df #6a749714 @desktop', async ({ page }) => {
    const impersonateResp = page.waitForResponse((r) => r.url().includes('/functions/v1/impersonate'));
    await impersonate(page, 'משה כהן');
    const resp = await impersonateResp;
    expect(resp.status()).toBe(200);
    expect(JSON.stringify(await resp.json().catch(() => ({})))).not.toContain('UNAUTHENTICATED');

    await expect(page).toHaveURL(/\/orders/);
    await expect(page.getByText('נציג מכירות').first()).toBeVisible();
    await expect(page.getByText('חזרה לחשבון הניהול')).toBeVisible();
    await expect(page.getByText('תמחור')).toHaveCount(0);

    await page.reload();
    await expect(page.getByText('מחובר/ת כרגע בתור משה כהן — כניסה כעובד פעילה')).toBeVisible();

    await page.goto('/team');
    await expect(page.getByText('שגיאה 403')).toBeVisible();

    await page.goto('/orders');
    await backToAdmin(page);
  });

  // back — текст кнопки на экране 403 (#22b2d92d: имя кнопки соответствует цели; у נהג не перепроверялось — любой «חזרה ל…»)
  const roles = [
    { employee: 'משה כהן', home: /\/orders/, back: 'חזרה להזמנות' },
    { employee: 'עובד מחסן בדיקה', home: /\/warehouse\/map/, back: 'חזרה למפת המחסן' },
    { employee: 'יוסי הנהג', home: /\/delivery/, back: null },
  ];
  for (const r of roles) {
    test(`${r.employee} — יעד נחיתה חוקי ו-403 בלי לולאה #6a672659 #22b2d92d @desktop`, async ({ page }) => {
      await impersonate(page, r.employee);
      await expect(page).toHaveURL(r.home);

      await page.goto('/shop');
      await expect(page.getByText('שגיאה 403')).toBeVisible();
      const backBtn = r.back
        ? page.getByRole('button', { name: r.back, exact: true })
        : page.getByRole('button', { name: /^חזרה ל(?!חשבון הניהול)/ }).or(page.getByRole('link', { name: /^חזרה ל(?!חשבון הניהול)/ })).first();
      await expect(backBtn).toBeVisible();
      if (r.back) await expect(page.getByRole('button', { name: 'חזרה לתנועות' })).toHaveCount(0);
      await backBtn.click();
      await expect(page).toHaveURL(r.home);
      await expect(page.getByText('שגיאה 403')).toHaveCount(0);

      await page.goto('/definitely-not-a-route');
      await expect(page).toHaveURL(r.home);

      await backToAdmin(page);
    });
  }
});

// ---- #22b2d92d / #dac8c6d1 (2026-10-05, עבר QA): кнопка 403 у עובד מחסן, баннер «כניסה כעובד» без обрезки, /no-access ----
// Ширины 1440/390/360/320 — через setViewportSize в десктопном прогоне (сценарий тикета — вёрстка на этих ширинах).
// «התנתקות» не нажимается (отзовёт токен сохранённой сессии admin).
const WIDTHS = [1440, 390, 360, 320];

/** Баннер (role=status): имя + «כניסה כעובד פעילה» целиком — ни один текстовый узел не переполнен и не обрезан «…»,
 *  всё внутри экрана; «חזרה לחשבון הניהול» видна. На < 640px « — » скрыт, «כניסה כעובד פעילה» — отдельной строкой. */
async function expectBannerFull(page: Page, employee: string, width: number) {
  const banner = page.getByRole('status').filter({ hasText: 'כניסה כעובד פעילה' });
  await expect(banner, `${width}px: баннер`).toBeVisible();
  await expect(banner).toContainText(`מחובר/ת כרגע בתור ${employee}`);
  for (const part of [employee, 'כניסה כעובד פעילה']) {
    await expect(banner.getByText(part, { exact: true }), `${width}px: «${part}» видно целиком`).toBeInViewport({ ratio: 1 });
  }
  const bad = await banner.evaluate((root) => {
    const out: string[] = [];
    const text = root.querySelector('span') as HTMLElement; // контейнер текста (без кнопки)
    for (const el of [text, ...Array.from(text.querySelectorAll<HTMLElement>('span, bdi'))]) {
      const cs = getComputedStyle(el);
      if (cs.display === 'none') continue;
      const r = el.getBoundingClientRect();
      if (el.scrollWidth > el.clientWidth + 1 && cs.display !== 'inline') out.push(`overflow: «${el.textContent}» ${el.scrollWidth}>${el.clientWidth}`);
      if (cs.textOverflow === 'ellipsis' && cs.overflow !== 'visible') out.push(`ellipsis: «${el.textContent}»`);
      if (r.left < -1 || r.right > innerWidth + 1) out.push(`out of screen: «${el.textContent}» ${Math.round(r.left)}..${Math.round(r.right)}`);
    }
    return out;
  });
  expect(bad, `${width}px: текст баннера без обрезки`).toEqual([]);
  await expect(page.getByText('חזרה לחשבון הניהול'), `${width}px: кнопка возврата`).toBeInViewport({ ratio: 1 });
}

test.describe('auth-security — 403 ובאנר «כניסה כעובד» (#22b2d92d #dac8c6d1)', () => {
  test.use({ storageState: auth('admin') });

  test('עובד מחסן: 403 ב-/team, /customers, /orders, /catalog/categories — «חזרה למפת המחסן» → «מפת המחסן» #22b2d92d @desktop', async ({ page }) => {
    await impersonate(page, 'עובד מחסן בדיקה');
    for (const url of ['/team', '/customers', '/orders', '/catalog/categories']) {
      await page.goto(url);
      await expect(page.getByRole('heading', { name: 'הגישה נחסמה' }), url).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('שגיאה 403')).toBeVisible();
      await expect(page.getByRole('button', { name: 'חזרה לתנועות' })).toHaveCount(0);
      const back = page.getByRole('button', { name: 'חזרה למפת המחסן', exact: true });
      await expect(back).toBeVisible();
      await back.click();
      await expect(page, `${url} → кнопка ведёт на карту склада`).toHaveURL(/\/warehouse\/map/);
      await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('שגיאה 403')).toHaveCount(0);
    }
    // узкие экраны: кнопка видна целиком
    await page.goto('/team');
    for (const w of [390, 360, 320]) {
      await page.setViewportSize({ width: w, height: 800 });
      await expect(page.getByRole('button', { name: 'חזרה למפת המחסן', exact: true }), `${w}px`).toBeInViewport({ ratio: 1 });
    }
    await page.setViewportSize({ width: 1440, height: 900 });
    await backToAdmin(page);
  });

  test('באנר «כניסה כעובד» מלא בלי «…» ב-1440/390/360/320 (403 ו-/orders); «חזרה לחשבון הניהול» → /team בלי באנר #dac8c6d1 @desktop', async ({ page }) => {
    const who = 'משה כהן';
    await impersonate(page, who);
    for (const url of ['/team', '/orders']) {
      await page.goto(url);
      if (url === '/team') await expect(page.getByText('שגיאה 403')).toBeVisible({ timeout: 20_000 });
      for (const w of WIDTHS) {
        await page.setViewportSize({ width: w, height: w > 1000 ? 900 : 800 });
        await expectBannerFull(page, who, w);
      }
    }
    // возврат с 403 на узком экране
    await page.goto('/team');
    await page.setViewportSize({ width: 360, height: 800 });
    await expect(page.getByText('שגיאה 403')).toBeVisible({ timeout: 20_000 });
    await page.getByText('חזרה לחשבון הניהול').click();
    await expect(page).toHaveURL(/\/team/, { timeout: 20_000 });
    await expect(page.getByText(/כניסה כעובד פעילה/)).toHaveCount(0);
    await expect(page.getByText('שגיאה 403')).toHaveCount(0);
    await page.setViewportSize({ width: 1440, height: 900 });
    await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible({ timeout: 20_000 });
  });

  for (const who of ['משה כהן', 'עובד מחסן בדיקה']) {
    test(`«אין אזור מוקצה» (/no-access) בכניסה כעובד — באנר מלא ו«חזרה לחשבון הניהול» (${who}) #dac8c6d1 @desktop`, async ({ page }) => {
      await impersonate(page, who);
      await page.goto('/no-access');
      await expect(page.getByRole('heading', { level: 1, name: 'אין אזור מוקצה' })).toBeVisible({ timeout: 20_000 });
      for (const w of WIDTHS) {
        await page.setViewportSize({ width: w, height: w > 1000 ? 900 : 800 });
        await expectBannerFull(page, who, w);
      }
      await page.getByText('חזרה לחשבון הניהול').click();
      await expect(page).toHaveURL(/\/team/, { timeout: 20_000 });
      await expect(page.getByText(/כניסה כעובד פעילה/)).toHaveCount(0);
      await page.setViewportSize({ width: 1440, height: 900 });
      await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
    });
  }
});

test.describe('auth-security — הרשאות שדורשות חשבון נוסף', () => {
  // auth-11: за rep («testtest») закреплён клиент «test» (2026-10-04). Берём ТОЛЬКО заказ «QA-AUTO-…» в статусе 'received'
  // (их оставляет client-ordering/cart-checkout). Ожидается отказ записи; если запись прошла — тест падает (дыра RLS),
  // а в finally исходный unit_price возвращается, чтобы не оставить 0.01 в заказе.
  test('נציג לא יכול לשנות unit_price ישירות דרך ה-API #6a6755e0 @desktop', async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: auth('rep'), baseURL: test.info().project.use.baseURL });
    const page = await ctx.newPage();
    try {
      await page.goto('/orders');
      await expect(page.getByText('נציג מכירות').first()).toBeVisible({ timeout: 20_000 });
      const res = await page.evaluate(async () => {
        let key: string | null = null;
        for (const src of [...document.scripts].map((s) => s.src).filter(Boolean)) {
          const t = await (await fetch(src)).text();
          const m = t.match(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/);
          if (m) { key = m[0]; break; }
        }
        const tokenKey = Object.keys(localStorage).find((k) => k.includes('auth-token'))!;
        const token = JSON.parse(localStorage.getItem(tokenKey)!).access_token;
        const ref = JSON.parse(atob(key!.split('.')[1])).ref as string;
        const url = `https://${ref}.supabase.co/rest/v1`;
        const h = { apikey: key!, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };
        const orders = await (await fetch(`${url}/orders?select=id,order_no&status=eq.received&note=like.QA-AUTO-*&order=created_at.desc&limit=1`, { headers: h })).json();
        if (!Array.isArray(orders) || !orders.length) return { skip: true as const };
        const items = await (await fetch(`${url}/order_items?select=id,unit_price&order_id=eq.${orders[0].id}&limit=1`, { headers: h })).json();
        if (!Array.isArray(items) || !items.length) return { skip: true as const };
        const item = items[0] as { id: string; unit_price: number };
        const patch = await fetch(`${url}/order_items?id=eq.${item.id}`, { method: 'PATCH', headers: h, body: JSON.stringify({ unit_price: 0.01 }) });
        const patchBody = await patch.json().catch(() => null);
        const after = (await (await fetch(`${url}/order_items?select=unit_price&id=eq.${item.id}`, { headers: h })).json())[0]?.unit_price as number;
        let restored: number | null = null;
        if (after === 0.01) {
          await fetch(`${url}/order_items?id=eq.${item.id}`, { method: 'PATCH', headers: h, body: JSON.stringify({ unit_price: item.unit_price }) });
          restored = (await (await fetch(`${url}/order_items?select=unit_price&id=eq.${item.id}`, { headers: h })).json())[0]?.unit_price;
        }
        return {
          skip: false as const, orderNo: orders[0].order_no, before: item.unit_price, after, restored,
          status: patch.status, rows: Array.isArray(patchBody) ? patchBody.length : -1,
        };
      });
      test.skip(res.skip, 'нет заказа QA-AUTO- в статусе received у клиента «test» (создаётся client-ordering/cart-checkout.spec.ts)');
      if (res.skip) return;
      test.info().annotations.push({ type: 'auth-11', description: `#${res.orderNo}: PATCH ${res.status}, строк ${res.rows}, unit_price ${res.before} → ${res.after}` });
      // Ожидаемо (AC #6a6755e0): запись отклонена (ошибка/0 строк) или цена приведена к effective_price — но не 0.01.
      // Если 0.01 записалось — дыра RLS; значение уже восстановлено выше (restored).
      expect(res.after, `unit_price в заказе #${res.orderNo} после попытки נציג записать 0.01 (восстановлено: ${res.restored})`).not.toBe(0.01);
    } finally {
      await ctx.close();
    }
  });

  test('לקוח מושבת לא מצליח להתחבר #6a38cf59', async () => {
    test.skip(true, 'нужен отдельный аккаунт לקוח для השבתה');
  });
});
